let cdqPdfAskStateV2284=null;

function cdqPdfDriveUrlV2282(id){
  id=String(id||'');
  if(!/^[A-Za-z0-9_-]+$/.test(id))throw new Error('Identifiant PDF invalide.');
  return 'https://drive.google.com/file/d/'+id+'/view?usp=drivesdk';
}

function cdqPdfDriveAppUrlV2284(id){
  id=String(id||'');
  const url=cdqPdfDriveUrlV2282(id);
  return /Android/i.test(navigator.userAgent||'')
    ? 'intent://drive.google.com/file/d/'+id+'/view?usp=drivesdk#Intent;scheme=https;package=com.google.android.apps.docs;S.browser_fallback_url='+encodeURIComponent(url)+';end'
    : url;
}

function cdqPdfMarkOpenedV2284(id){
  if(String(utilisateurCourantRole||'')==='lecture')return;
  try{
    fichierOuvertPourModification=id;
    sessionStorage.setItem('fichierEnModification',id);
    sessionStorage.setItem('ancienneDateModification',String((cdqDocumentMeta(id)||{}).dateModification||''));
    sessionStorage.setItem('momentModification',String(Date.now()));
  }catch(_){}
}

function cdqPdfAskCloseV2284(){
  const old=document.getElementById('cdqPdfAskReadyV2284');
  if(old)old.remove();
}

function cdqPdfAskReadyV2284(state,rec){
  cdqPdfAskCloseV2284();

  const overlay=document.createElement('div');
  overlay.id='cdqPdfAskReadyV2284';
  overlay.style.cssText='position:fixed;inset:0;z-index:100600;display:flex;align-items:center;justify-content:center;padding:18px;background:rgba(2,10,18,.76)';

  const name=String((rec&&rec.nom)||state.name||'Rapport.pdf').replace(/[\\/\x00-\x1f]/g,'_').slice(0,180);
  const file=new File([rec.blob],/\.pdf$/i.test(name)?name:name+'.pdf',{type:'application/pdf'});

  overlay.innerHTML=
    '<div style="width:min(430px,100%);border:1px solid #168dc2;border-radius:18px;background:#071a29;color:#f4fbff;padding:18px;box-shadow:0 20px 60px rgba(0,0,0,.55)">'+
      '<strong style="display:block;font-size:20px">PDF prêt</strong>'+
      '<div style="margin-top:8px;color:#afc7d5;line-height:1.45">'+
        'Compte Google : <b>'+String(state.email||'sélectionné')+'</b><br>'+
        '<span style="word-break:break-word">'+file.name+'</span>'+
      '</div>'+
      '<button id="cdqPdfAskOpenV2284" type="button" style="width:100%;min-height:54px;margin-top:16px;border:0;border-radius:12px;background:#199fe0;color:white;font-weight:900;font-size:16px">Ouvrir avec…</button>'+
      '<button id="cdqPdfAskCancelV2284" type="button" style="width:100%;min-height:48px;margin-top:10px;border:1px solid #31556c;border-radius:12px;background:#10283b;color:white;font-weight:800">Annuler</button>'+
    '</div>';

  document.body.appendChild(overlay);

  overlay.querySelector('#cdqPdfAskCancelV2284').onclick=function(){
    cdqPdfAskStateV2284=null;
    overlay.remove();
  };

  overlay.querySelector('#cdqPdfAskOpenV2284').onclick=async function(){
    const btn=this;
    const payload={files:[file],title:file.name};

    if(!(navigator.share&&(!navigator.canShare||navigator.canShare(payload)))){
      afficherMessage('Le sélecteur Android des applications PDF n’est pas disponible.',false);
      return;
    }

    try{
      btn.disabled=true;
      btn.textContent='Ouverture…';
      await navigator.share(payload);
      cdqPdfAskStateV2284=null;
      overlay.remove();
    }catch(e){
      btn.disabled=false;
      btn.textContent='Ouvrir avec…';
      if(!e||e.name!=='AbortError'){
        afficherMessage('Android n’a pas pu afficher les applications PDF. Réessayez.',false);
      }
    }
  };
}

async function cdqPdfAskPrepareRealFileV2284(state){
  afficherMessage('Préparation du PDF…',true);
  try{
    cdqPdfMarkOpenedV2284(state.id);
    const rec=await cdqLoadPdfRecord(state.id);
    if(!rec||!(rec.blob instanceof Blob)||rec.blob.type!=='application/pdf'||rec.blob.size<5){
      throw new Error('Le PDF reçu est invalide.');
    }
    cdqPdfAskReadyV2284(state,rec);
  }catch(e){
    cdqPdfAskStateV2284=null;
    afficherErreur(e);
  }
}

function cdqPdfAskAccountV2284(id){
  const meta=cdqDocumentMeta(id)||{};
  const requestId='pdf-'+crypto.randomUUID();

  cdqPdfAskStateV2284={
    requestId:requestId,
    id:String(id),
    name:String(meta.nom||'Rapport.pdf'),
    challengeId:'',
    email:''
  };

  afficherMessage('Choisissez le compte Google pour ouvrir le PDF.',true);

  cdqApiRun()
    .withSuccessHandler(function(defi){
      const st=cdqPdfAskStateV2284;
      if(!st||st.requestId!==requestId)return;

      if(!defi||!defi.challengeId||!defi.nonce||!defi.clientId){
        cdqPdfAskStateV2284=null;
        afficherMessage('Impossible de préparer le choix du compte Google.',false);
        return;
      }

      st.challengeId=String(defi.challengeId);

      // Réutilise exactement le sélecteur Google déjà présent et stable
      // dans Balance CDQ. Aucun nouveau dialogue PDF n'est créé ici.
      cdqPostToPwa({
        type:'CDQ_GOOGLE_AUTH_REQUIRED',
        authProtocol:42,
        message:'Choisissez le compte Google pour ouvrir le PDF.',
        challengeId:String(defi.challengeId),
        nonce:String(defi.nonce),
        clientId:String(defi.clientId),
        expiresAt:Number(defi.expiresAt)||0
      });
    })
    .withFailureHandler(function(e){
      cdqPdfAskStateV2284=null;
      afficherMessage(e&&e.message?e.message:String(e),false);
    })
    .creerDefiConnexionGoogleCDQ();
}

// Important : capture=true permet au flux PDF "Demander" de récupérer
// le credential AVANT le gestionnaire de connexion générale de Balance CDQ.
window.addEventListener('message',function(e){
  if(!cdqFromPwa(e))return;

  const d=e.data||{};
  const st=cdqPdfAskStateV2284;

  if(!st||d.type!=='CDQ_GOOGLE_CREDENTIAL')return;
  if(!d.credential||!d.challengeId||String(d.challengeId)!==String(st.challengeId))return;

  e.stopImmediatePropagation();

  const requestId=st.requestId;

  cdqApiRun()
    .withSuccessHandler(function(resultat){
      const current=cdqPdfAskStateV2284;
      if(!current||current.requestId!==requestId)return;

      if(!resultat||!resultat.ok){
        cdqPdfAskStateV2284=null;
        cdqPostToPwa({type:'CDQ_GOOGLE_AUTH_HIDE'});
        afficherMessage('Google n’a pas confirmé ce compte.',false);
        return;
      }

      current.email=String(resultat.email||'');
      cdqPostToPwa({type:'CDQ_GOOGLE_AUTH_HIDE'});
      cdqPdfAskPrepareRealFileV2284(current);
    })
    .withFailureHandler(function(err){
      cdqPdfAskStateV2284=null;
      cdqPostToPwa({type:'CDQ_GOOGLE_AUTH_HIDE'});
      afficherMessage(err&&err.message?err.message:String(err),false);
    })
    .verifierJetonGoogleCDQ(String(d.credential),String(d.challengeId));
},true);

function cdqV19OpenDrivePdfV2284(id){
  const pref=typeof cdqPdfReaderPreference==='function'
    ? cdqPdfReaderPreference()
    : 'ask';

  // Pour cette version, on ne corrige QUE "Demander".
  if(pref==='ask'){
    cdqPdfAskAccountV2284(id);
    return;
  }

  // Les autres préférences restent sur le chemin Drive stable
  // jusqu'à ce que le mode Demander soit validé.
  const a=document.createElement('a');
  a.href=cdqPdfDriveAppUrlV2284(id);
  a.target='_blank';
  a.rel='noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();
  cdqPdfMarkOpenedV2284(id);
}

const cdqV19OldModify=window.modifierFichier;
window.modifierFichier=function(id){
  const meta=cdqDocumentMeta(id);

  if(meta&&meta.type==='GOOGLE_SHEETS'){
    cdqV19OpenOfflineSheet(id);
    return;
  }

  if(meta&&meta.type==='PDF'){
    if(navigator.onLine!==false){
      cdqV19OpenDrivePdfV2284(id);
      return;
    }
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  if(!navigator.onLine){
    afficherMessage('Ouvrez ce fichier dans son application après l’avoir enregistré sur le téléphone.',false);
    return;
  }

  return cdqV19OldModify(id);
};
